--[[ WDYM HUB · PROTECTED SCRIPT ]]--
local _b64 = ""

local function _dec(_data)
    local _b = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    local _lookup = {}
    for i = 1, #_b do
        _lookup[_b:sub(i, i)] = i - 1
    end
    
    local _clean = _data:gsub('[^A-Za-z0-9%+/=]', '')
    local _out = {}
    local _len = #_clean
    local _c = 1

    for i = 1, _len, 4 do
        local c1 = _lookup[_clean:sub(i, i)] or 0
        local c2 = _lookup[_clean:sub(i+1, i+1)] or 0
        local c3 = _lookup[_clean:sub(i+2, i+2)] or 0
        local c4 = _lookup[_clean:sub(i+3, i+3)] or 0

        local b1 = bit32.lshift(c1, 2) + bit32.rshift(c2, 4)
        local b2 = bit32.lshift(bit32.band(c2, 15), 4) + bit32.rshift(c3, 2)
        local b3 = bit32.lshift(bit32.band(c3, 3), 6) + c4

        _out[_c] = string.char(b1)
        _c = _c + 1
        if _clean:sub(i+2, i+2) ~= '=' then
            _out[_c] = string.char(b2)
            _c = _c + 1
        end
        if _clean:sub(i+3, i+3) ~= '=' then
            _out[_c] = string.char(b3)
            _c = _c + 1
        end
    end
    return table.concat(_out)
end

local _src = _dec(_b64)
local _fn, _err = (loadstring or load)(_src)
if _fn then
    _fn()
else
    warn("[WDYM Engine Load Error]: " .. tostring(_err))
end
